#include <iostream>
using namespace std;

class BasicSkill{
protected:
    int basicDamage;

public:
    BasicSkill(int b = 0){
        if (b < 0) throw "basicDamage cannot be negative!";
        basicDamage = b;
    }
    virtual void displayDamage(){
        cout << "Basic Damage: " << basicDamage << endl;
    }
    BasicSkill operator + (int value){
        return BasicSkill(basicDamage + value);
    }
    friend ostream & operator << (ostream& out, BasicSkill& a){
        cout << "Basic Damage: " << a.basicDamage << endl;
        return out;
    }
};

class SpecialSkill: public BasicSkill{
private:
    int bonusDamage;

public:
    SpecialSkill(int b = 0, int bd = 0): BasicSkill(b){
        if (bd < 0) throw "bonusDamage cannot be negative!";
        bonusDamage = bd;
    }
    void displayDamage(){
        cout << "Basic Damage: " << basicDamage << endl;
        cout << "Bonus Damage: " << bonusDamage << endl;
    }
    SpecialSkill operator + (int value){
        return SpecialSkill(basicDamage + value, bonusDamage + value);
    }
    friend ostream & operator << (ostream& out, SpecialSkill& A){
        cout << "Basic Damage: " << A.basicDamage << endl;
        cout << "Bonus Damage: " << A.bonusDamage;
        return out;
    }
};

int main(){
    try{
        BasicSkill bs1, bs2(100);
        SpecialSkill ss1;
        SpecialSkill ss2(100, 50);

        cout << "BasicSkill 1 Details\n";
        bs1.displayDamage();
        cout << "--------------------\n";
        cout << "\n BasicSkill 2 Details\n";
        bs2.displayDamage();
        cout << "--------------------\n";
        cout << "\nSpecialSkill 1 Details\n";
        ss1.displayDamage();
        cout << "--------------------\n";
        cout << "\nSpecialSkill 2 Details\n";
        ss2.displayDamage();
        cout << "--------------------\n";

        int upgrade;
        cout << "\n Upgrade: ";
        cin >> upgrade;

        if(cin.fail())
            throw "\n Invalid Input";
        if(upgrade < 0)
            throw "\n Invalid Input";

        bs1 = bs1 + upgrade;
        bs2 = bs2 + upgrade;
        ss1 = ss1 + upgrade;
        ss2 = ss2 + upgrade;

        cout << "BasicSkill 1 Details\n" << bs1 << endl;
        cout << "--------------------\n";
        cout << "\n BasicSkill 2 Details\n" << bs2 << endl;
        cout << "--------------------\n";
        cout << "\nSpecialSkill 1 Details\n" << ss1 << endl;
        cout << "--------------------\n";
        cout << "\nSpecialSkill 2 Details\n" << ss2 << endl;
        cout << "--------------------\n";
    }
    catch(const char* msg){
        cout << "\n Error" << msg << endl;
    }
    return 0;
}

